//! Replays tasks_ts_vectors.json (outcomes of the real flag-off userTaskService,
//! regenerated by workTaskVectors.test.ts) through the Rust `task*` work ops.
use serde_json::{Map, Value, json};

use super::run_json;

fn vectors() -> Value {
    serde_json::from_str(include_str!("tasks_ts_vectors.json")).expect("vectors parse")
}

fn run(op: &str, input: &Value, name: &Value) -> Value {
    let output = run_json(op, &input.to_string()).unwrap_or_else(|e| panic!("{op} {name}: {e}"));
    serde_json::from_str(&output).expect("output json")
}

#[test]
fn views_envelopes_and_paths_equal_typescript() {
    let doc = vectors();
    let views = doc["views"].as_array().expect("views");
    assert!(views.len() >= 15, "every view case is recorded");
    for case in views.iter().chain(doc["paths"].as_array().expect("paths")) {
        let op = case["op"].as_str().expect("op");
        assert_eq!(run(op, &case["input"], &case["name"]), case["expected"], "{op}: {}", case["name"]);
    }
}

/// The page's AAD-bound decrypt in the vector stub: `sealedaad:<aad>|<plaintext>`.
fn open_with_aad(ciphertext: &Value, aad: &str) -> Option<String> {
    ciphertext.as_str()?.strip_prefix(&format!("sealedaad:{aad}|")).map(str::to_owned)
}

#[test]
fn activity_entries_equal_typescript() {
    let doc = vectors();
    let cases = doc["activity"].as_array().expect("activity");
    assert!(cases.len() >= 5, "every activity case is recorded");
    for case in cases {
        let decided = run("taskActivityView", &case["input"], &case["name"]);
        let outcome = if decided.get("error").is_some() {
            decided
        } else {
            // Performs the decrypts like userTaskService's flag-on branch.
            let mut entry = decided["entry"].as_object().expect("entry").clone();
            let mut failed = None;
            for step in decided["decrypts"].as_array().expect("decrypts") {
                let ciphertext = &case["input"]["record"][step["member"].as_str().expect("member")];
                match open_with_aad(ciphertext, step["aad"].as_str().expect("aad")) {
                    Some(plaintext) => {
                        entry.insert(step["name"].as_str().expect("name").to_owned(), json!(plaintext));
                    }
                    None => {
                        failed = Some(json!({ "error": step["failure"] }));
                        break;
                    }
                }
            }
            failed.unwrap_or(Value::Object(entry))
        };
        assert_eq!(outcome, case["expected"], "taskActivityView: {}", case["name"]);
    }
}

/// Applies the ordered steps like workRust.ts `buildWorkBody` with the test stub
/// (`sealed:<key byte>:[<aad>|]<plaintext>`), recording the encryption call order.
fn assemble(case: &Value, request: &Value) -> (Value, Vec<Value>) {
    let expected_body = &case["expected"]["body"];
    let mut body = Map::new();
    let mut calls = Vec::new();
    for step in request["steps"].as_array().expect("steps") {
        let name = step[0].as_str().expect("step name");
        let action = &step[1];
        let mut seal = |text: &str, role: &Value, aad: Option<&str>| {
            let byte = &case["keys"][role.as_str().expect("key role")];
            calls.push(json!([text, byte, aad]));
            match aad {
                Some(aad) => json!(format!("sealed:{byte}:{aad}|{text}")),
                None => json!(format!("sealed:{byte}:{text}")),
            }
        };
        let value = if let Some(value) = action.get("value") {
            value.clone()
        } else if let Some(text) = action.get("encrypt") {
            seal(text.as_str().expect("plaintext"), &action["key"], action.get("aad").and_then(Value::as_str))
        } else if let Some(member) = action.get("encrypt_input") {
            let text = case["encrypt_inputs"][member.as_str().expect("member")].as_str().expect("page json");
            seal(text, &action["key"], None)
        } else {
            // Slots are page-made (wrapped key, blind index, key wrappers): taken from the TS body.
            expected_body[action["slot"].as_str().expect("slot")].clone()
        };
        body.insert(name.to_owned(), value);
    }
    (Value::Object(body), calls)
}

/// The wrapper facts must name exactly the chat/projects the TS wrappers were built for.
/// Ops without wrapper facts (`taskKeyWrappersAddBody`) pass page-made wrappers through.
fn assert_wrapper_targets(case: &Value, request: &Value) {
    let Some(wrappers) = case["expected"]["body"]["key_wrappers"].as_array() else {
        return;
    };
    if request.get("wrapper_project_ids").is_none() {
        return;
    }
    let chat: Vec<Value> = wrappers.iter().filter_map(|w| w.get("hashed_chat_id").cloned()).collect();
    let expected_chat: Vec<Value> =
        request["wrapper_chat_id"].as_str().map(|id| json!(format!("hash:{id}"))).into_iter().collect();
    assert_eq!(chat, expected_chat, "chat target: {}", case["name"]);
    let projects: Vec<Value> = wrappers.iter().filter_map(|w| w.get("hashed_project_id").cloned()).collect();
    let expected_projects: Vec<Value> = request["wrapper_project_ids"]
        .as_array()
        .expect("wrapper project ids")
        .iter()
        .map(|id| json!(format!("hash:{}", id.as_str().expect("project id"))))
        .collect();
    assert_eq!(projects, expected_projects, "project targets: {}", case["name"]);
}

#[test]
fn request_bodies_equal_typescript() {
    let doc = vectors();
    let bodies = doc["bodies"].as_array().expect("bodies");
    assert!(bodies.len() >= 25, "every body case is recorded");
    for case in bodies {
        let op = case["op"].as_str().expect("op");
        let request = run(op, &case["input"], &case["name"]);
        if let Some(error) = case["expected"].get("error") {
            assert_eq!(request.get("error"), Some(error), "{op}: {}", case["name"]);
            continue;
        }
        assert_eq!(request["path"], case["expected"]["path"], "{op} path: {}", case["name"]);
        assert_eq!(request["method"], case["expected"]["method"], "{op} method: {}", case["name"]);
        let (body, calls) = assemble(case, &request);
        assert_eq!(body, case["expected"]["body"], "{op} body: {}", case["name"]);
        assert_eq!(Value::Array(calls), case["expected"]["encrypt_calls"], "{op} encryption order: {}", case["name"]);
        assert_wrapper_targets(case, &request);
    }
}

#[test]
fn malformed_task_inputs_are_refused() {
    assert_eq!(run_json("taskNothing", "{}").unwrap_err(), "unknown_op:taskNothing");
    assert_eq!(run_json("taskView", "{}").unwrap_err(), "missing_field:record");
    let bad_action = json!({ "task": { "task_id": "t" }, "action": "delete" });
    assert_eq!(run_json("taskActionBody", &bad_action.to_string()).unwrap_err(), "bad_field:action");
    let missing_plaintext = json!({ "record": { "task_id": "t", "version": 1, "encrypted_title": "c" }, "fields": {} });
    assert_eq!(run_json("taskView", &missing_plaintext.to_string()).unwrap_err(), "missing_field:fields.encrypted_title");
}

#[test]
fn malformed_linked_project_json_is_refused_not_defaulted() {
    let input = json!({
        "record": { "task_id": "t", "version": 1, "encrypted_linked_project_ids": "c" },
        "fields": { "encrypted_linked_project_ids": "[1," },
        "team_id": null,
    });
    let output: Value = serde_json::from_str(&run_json("taskView", &input.to_string()).expect("decision")).expect("json");
    assert_eq!(output, json!({ "error": "Task linked Project ids is not valid JSON" }));
}
